schema.content:
Table "car_makers" {
  "Id" INTEGER [pk]
  "Maker" TEXT
  "FullName" TEXT
  "Country" TEXT
}

Table "car_names" {
  "MakeId" INTEGER [pk]
  "Model" TEXT
  "Make" TEXT
}

Table "cars_data" {
  "Id" INTEGER [pk]
  "MPG" TEXT
  "Cylinders" INTEGER
  "Edispl" REAL
  "Horsepower" TEXT
  "Weight" INTEGER
  "Accelerate" REAL
  "Year" INTEGER
}

Table "continents" {
  "ContId" INTEGER [pk]
  "Continent" TEXT
}

Table "countries" {
  "CountryId" INTEGER [pk]
  "CountryName" TEXT
  "Continent" INTEGER
}

Table "model_list" {
  "ModelId" INTEGER [pk]
  "Maker" INTEGER
  "Model" TEXT
}



Ref: "countries"."Continent" > "continents"."ContId"

Ref: "car_makers"."Country" > "countries"."CountryId"

Ref: "model_list"."Maker" > "car_makers"."Id"

Ref: "car_names"."Model" > "model_list"."Model"

Ref: "cars_data"."Id" > "car_names"."MakeId"
